/* Tombstone for the Chirpy PWA service worker.
 *
 * From the site's first commit (2025-06-04) until the Jekyll config was
 * rewritten (5bf3ab7, 2026-05-26), `pwa.enabled: true` shipped Chirpy's
 * service worker at this exact URL, scoped to the whole origin. Its fetch
 * handler was cache-first with no expiry: once a page or asset landed in
 * Cache Storage it was served from there forever, so every browser that
 * visited leosun.org in that year still renders the old site and never asks
 * the network. Deleting the file is not enough — a 404 on the update check
 * leaves the old worker registered and still in control.
 *
 * So the URL keeps answering, with a worker whose only job is to undo the
 * old one: wipe every cache, unregister itself, and reload the open tabs
 * onto the live site. No fetch handler, so the browser bypasses it for
 * network requests in the meantime.
 *
 * This file must outlive the visitors it is repairing. Do not delete it.
 */
self.addEventListener('install', () => {
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(keys.map((key) => caches.delete(key)));

      // Claim before unregistering: `client.navigate()` is only allowed on
      // clients this worker actually controls, and the open tabs are still
      // held by the old worker until we take them.
      await self.clients.claim();
      await self.registration.unregister();

      const windows = await self.clients.matchAll({ type: 'window' });
      for (const client of windows) {
        client.navigate(client.url).catch(() => {});
      }
    })()
  );
});
